"use client";

import { useActionState, useState } from "react";
import { Badge, Button, Callout, Field, Input, Segmented } from "@/components/ui";
import { signInDetailsText } from "@/lib/sign-in-details";
import { addPersonAction, removePersonAction, resetPasswordAction, type PeopleState } from "@/server/people/actions";

export type Person = {
  id: number;
  username: string;
  role: "owner" | "staff";
  lastLogin: string | null;
  mustChangePassword: boolean;
};

/**
 * Settings → People (owner only, R1). Passwords are always generated by the app,
 * shown once here with copy buttons (each field, or a ready-to-send message), and changed by the person at first sign-in.
 */
export function PeoplePanel({ people, meId }: { people: Person[]; meId: number }) {
  const [added, add, adding] = useActionState<PeopleState, FormData>(addPersonAction, {});
  const [reset, doReset, resetting] = useActionState<PeopleState, FormData>(resetPasswordAction, {});
  const [removed, remove, removing] = useActionState<PeopleState, FormData>(removePersonAction, {});
  const [confirmId, setConfirmId] = useState<number | null>(null);

  const latest = [added, reset, removed].sort((a, b) => (b.version ?? 0) - (a.version ?? 0))[0]!;

  return (
    <div className="flex flex-col">
      {latest.error ? (
        <div className="p-4 pb-0">
          <Callout tone="danger">{latest.error}</Callout>
        </div>
      ) : null}
      {latest.password ? (
        <div className="p-4 pb-0">
          <OneTimePassword username={latest.username ?? ""} password={latest.password} />
        </div>
      ) : null}
      <ul aria-label="People" className="divide-y divide-border">
        {people.map((p) => (
          <li key={p.id} className="flex flex-wrap items-center gap-x-3 gap-y-2 px-4 py-2.5">
            <div className="min-w-0 flex-1">
              <p className="flex flex-wrap items-center gap-2 font-medium">
                {p.username}
                <Badge tone={p.role === "owner" ? "info" : "neutral"}>{p.role === "owner" ? "Owner" : "Staff"}</Badge>
                {p.mustChangePassword ? <Badge tone="warning">Hasn&apos;t chosen a password yet</Badge> : null}
              </p>
              <p className="text-sm text-ink-muted">
                {p.lastLogin ? `Last sign-in ${p.lastLogin}` : "Never signed in"}
              </p>
            </div>
            {p.id === meId ? (
              <span className="text-sm text-ink-muted">You</span>
            ) : (
              <div className="flex gap-1">
                <form action={doReset}>
                  <input type="hidden" name="id" value={p.id} />
                  <input type="hidden" name="username" value={p.username} />
                  <Button type="submit" variant="quiet" pending={resetting}>
                    Reset password
                  </Button>
                </form>
                {confirmId === p.id ? (
                  <form action={remove} className="flex gap-1">
                    <input type="hidden" name="id" value={p.id} />
                    <Button type="submit" variant="danger" pending={removing}>
                      Remove {p.username}
                    </Button>
                    <Button variant="quiet" onClick={() => setConfirmId(null)}>
                      Keep
                    </Button>
                  </form>
                ) : (
                  <Button variant="quiet" onClick={() => setConfirmId(p.id)}>
                    Remove
                  </Button>
                )}
              </div>
            )}
          </li>
        ))}
      </ul>
      <form
        key={added.password ? added.version : "add"}
        action={add}
        className="flex flex-col gap-3 border-t border-border p-4 sm:flex-row sm:items-end"
      >
        <div className="flex-1">
          <Field id="new-username" label="Add person: username">
            <Input
              id="new-username"
              name="username"
              autoCapitalize="none"
              spellCheck={false}
              defaultValue={added.password ? "" : added.username}
              required
            />
          </Field>
        </div>
        <Segmented
          name="role"
          legend="Role"
          options={[
            { value: "staff", label: "Staff" },
            { value: "owner", label: "Owner" },
          ]}
        />
        <Button type="submit" variant="secondary" pending={adding}>
          Add person
        </Button>
      </form>
      <p className="border-t border-border px-4 py-3 text-xs text-ink-muted">
        Staff can do everything except adjust stock, download backups, see Change history and manage people. The app
        makes the password; the person picks their own at first sign-in.
      </p>
    </div>
  );
}

function OneTimePassword({ username, password }: { username: string; password: string }) {
  return (
    <Callout tone="success" title={`Sign-in details for ${username}`}>
      <dl className="flex flex-col gap-2 pt-2">
        <CopyRow label="Username" value={username} />
        <CopyRow label="One-time password" value={password} />
      </dl>
      <div className="flex flex-wrap items-center gap-x-3 gap-y-2 pt-3">
        <CopyButton
          variant="secondary"
          label="Copy sign-in details"
          // Built at click time so the link matches the address the owner is using.
          text={() => signInDetailsText({ username, password, signInUrl: `${window.location.origin}/login` })}
        />
        <span className="text-sm">Copies the link, username and password, ready to send.</span>
      </div>
      <p className="pt-2 text-sm text-ink-soft">
        Shown only once. They&apos;ll choose their own password when they sign in.
      </p>
    </Callout>
  );
}

function CopyRow({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex flex-wrap items-center gap-x-3 gap-y-1">
      <dt className="w-full text-sm text-ink-soft sm:w-36">{label}</dt>
      <dd className="min-w-0 flex-1 sm:flex-none">
        <code className="block truncate rounded-sm bg-surface px-2 py-1 font-mono text-md tracking-wide text-ink select-all">
          {value}
        </code>
      </dd>
      <dd>
        <CopyButton variant="quiet" label="Copy" what={label.toLowerCase()} text={value} />
      </dd>
    </div>
  );
}

function CopyButton({
  label,
  what,
  text,
  variant,
}: {
  label: string;
  /** Screen-reader-only suffix, e.g. "username" → "Copy username" / "Copied username". */
  what?: string;
  text: string | (() => string);
  variant: "secondary" | "quiet";
}) {
  const [state, setState] = useState<"idle" | "copied" | "failed">("idle");
  return (
    <Button
      variant={variant}
      // Fixed width so "Copy" → "Copied" doesn't shift the row.
      className={variant === "quiet" ? "w-24" : undefined}
      onClick={async () => {
        try {
          await navigator.clipboard.writeText(typeof text === "function" ? text() : text);
          setState("copied");
        } catch {
          setState("failed");
        }
        setTimeout(() => setState("idle"), 2000);
      }}
    >
      <span aria-live="polite">
        {state === "copied" ? "Copied" : state === "failed" ? "Copy failed" : label}
        {what ? <span className="sr-only"> {what}</span> : null}
      </span>
    </Button>
  );
}
